'use strict';
// Independent replacement acceptance: actual SQLite/application/password work,
// Node Ed25519 and separately written fixed signature arrays/domains. All data
// are synthetic; this is not real OS-vault, UI, provider or Mac acceptance.
const nodeTest=require('node:test'),assert=require('node:assert/strict');
const test=(name,run)=>nodeTest(name,{timeout:20000},run);
const {DatabaseSync}=require('node:sqlite'),{createHash,generateKeyPairSync,randomUUID,randomBytes,sign}=require('node:crypto');
const {pathToFileURL}=require('node:url'),path=require('node:path'),fs=require('node:fs/promises');
const {createTeamClient}=require('../desktop/team-client.cjs'),{registerDesktopBridge,APP_URL}=require('../desktop/bridge.cjs');
const source=name=>import(pathToFileURL(path.resolve(__dirname,'../server/team/'+name)).href);
const NOW=Date.parse('2026-11-15T18:00:00Z'),PASSWORD='ReplacementSynthetic!2026',ORIGIN='http://127.0.0.1:8774';
const CF=['purpose','serverId','userId','sessionBinding','keyFingerprint','identityEpoch','bindingRevision','approvalRequestId','challengeId','nonce','issuedAt','expiresAt'];
const XF=['purpose','serverId','userId','sessionBinding','keyFingerprint','identityEpoch','oldDeviceId','oldBindingRevision','oldBindingStatus','requestId','requestRevision','challengeId','nonce','issuedAt','expiresAt'];
const RF=['serverId','userId','sessionBinding','deviceId','bindingRevision','leaseId','method','pathAndQuery','bodySha256','nonce'];
const digest=v=>createHash('sha256').update(v).digest('hex');
const payload=(domain,fields,order)=>Buffer.concat([Buffer.from(domain+'\0v1\0','ascii'),Buffer.from(JSON.stringify(order.map(k=>fields[k])),'utf8')]);
const oldBytes=v=>payload('SHENYI-DEVICE-PROOF',v,CF),replacementBytes=v=>payload('SHENYI-DEVICE-REPLACEMENT',v,XF),requestBytes=v=>payload('SHENYI-DEVICE-REQUEST',v,RF);
const keyPair=()=>{const pair=generateKeyPairSync('ed25519'),der=pair.publicKey.export({format:'der',type:'spki'});return {...pair,encoded:der.toString('base64url'),fingerprint:digest(der)};};
const deferred=()=>{let resolve;return {promise:new Promise(r=>resolve=r),resolve};};
const rejected=(r,statuses=[400,401,403,404,409,410])=>{assert.ok(statuses.includes(r.status),'Unexpected status '+r.status+' '+r.raw);assert.ok(!r.raw.includes('Synthetic injected'));assert.ok(!r.raw.includes('password_hash'));assert.ok(!r.raw.includes('private-provider'));};
const succeeds=(r,statuses=[200,201])=>{assert.ok(statuses.includes(r.status),r.status+' '+r.raw);return r;};
const preserveTables=['team_users','team_credentials','team_phone_credentials','team_wechat_identities','team_memberships','team_operators','team_project_grants','team_attachment_grants','team_task_assignments','team_task_versions','team_task_submissions','team_collection_attachments','team_projects'];
let passwordHash;
async function fixture(t){
 const [{initializeTeamDatabase},{hashPassword},{issueSession},{handleTeamApplicationRequest}]=await Promise.all([source('database.mjs'),source('passwords.mjs'),source('auth-api.mjs'),source('application-api.mjs')]);passwordHash||=hashPassword(PASSWORD);const db=new DatabaseSync(':memory:');initializeTeamDatabase(db);t.after(()=>db.close());
 assert.ok(db.prepare("SELECT 1 FROM sqlite_schema WHERE name='team_device_replacement_requests'").get(),'Real initialize must install replacement schema');
 for(const user of ['intern-a','assistant-b','manager-a','partner-a','tech-a','tech-b','owner','provision-owner','recovery-owner','access-owner']){db.prepare("INSERT INTO team_users VALUES (?,'active')").run(user);db.prepare('INSERT INTO team_credentials(user_id,username,display_name,password_hash) VALUES (?,?,?,?)').run(user,user,'Synthetic '+user,await passwordHash);}
 for(const team of ['a','b']){db.prepare("INSERT INTO teams VALUES (?,'active')").run('team-'+team);db.prepare('INSERT INTO team_profiles VALUES (?,?)').run('team-'+team,'Synthetic '+team);db.prepare("INSERT INTO team_projects(team_id,project_id,title,status) VALUES (?,?,?,'active')").run('team-'+team,'project-'+team,'Synthetic project');}
 for(const [user,team,role]of [['intern-a','a','intern'],['assistant-b','b','assistant'],['manager-a','a','manager'],['partner-a','a','partner']])db.prepare("INSERT INTO team_memberships VALUES (?,?,?,'active')").run('team-'+team,user,role);
 for(const team of ['a','b'])db.prepare("INSERT INTO team_operators VALUES (?,?,'administrator','active')").run('team-'+team,'tech-'+team);
 db.prepare("INSERT INTO team_device_replacement_reviewers VALUES ('owner','device.replace','active',1)").run();db.prepare("INSERT INTO team_platform_reviewers VALUES ('provision-owner','team.provision','active',1)").run();db.prepare("INSERT INTO team_recovery_reviewers VALUES ('recovery-owner','account.recover','active',1)").run();db.prepare("INSERT INTO team_access_reviewers VALUES ('access-owner','member.disable','active',1)").run();
 db.prepare("INSERT INTO team_phone_credentials VALUES ('intern-a','+8613800138000',?,1)").run(NOW-1000);db.prepare("INSERT INTO team_wechat_identities VALUES ('wx0123456789abcdef','synthetic-open','intern-a',?)").run(NOW-1000);
 db.prepare("INSERT INTO team_collection_tasks(team_id,task_id,project_id,title,instructions,status) VALUES ('team-a','task-a','project-a','Synthetic task','No customer data','open')").run();db.prepare("INSERT INTO team_task_assignments VALUES ('team-a','task-a','intern-a','active')").run();for(const permission of ['collection.read','collection.manage'])db.prepare("INSERT INTO team_project_grants VALUES ('team-a','project-a','manager-a',?,'active')").run(permission);
 const f={db,now:NOW,actors:new Map(),calls:[],providers:{deviceProofRequired:true}};
 f.bootstrap=user=>issueSession(db,user,f.now).token;
 f.request=(route,{token,method='GET',body,rawBody,headers={}}={})=>new Request(ORIGIN+route,{method,headers:{Origin:'shenyi://app',...(token?{Authorization:'Bearer '+token}:{}),...(body!==undefined||rawBody!==undefined?{'Content-Type':'application/json'}:{}),...headers},...(body!==undefined||rawBody!==undefined?{body:rawBody===undefined?JSON.stringify(body):rawBody,...(rawBody instanceof ReadableStream?{duplex:'half'}:{})}:{})});
 f.send=async request=>{const response=await handleTeamApplicationRequest(request,{db,now:()=>f.now,identityProviders:f.providers});assert.ok(response,'Route must dispatch');const bytes=Buffer.from(await response.arrayBuffer()),raw=bytes.toString('utf8'),data=bytes.length&&response.headers.get('content-type')?.startsWith('application/json')?JSON.parse(raw):null;f.calls.push({method:request.method,path:new URL(request.url).pathname,status:response.status});return {status:response.status,headers:response.headers,data,bytes,raw};};
 f.call=(route,options)=>f.send(f.request(route,options));
 f.transport=async(url,settings={})=>{let response=await handleTeamApplicationRequest(new Request(url,{...settings,headers:settings.headers}),{db,now:()=>f.now,identityProviders:f.providers});assert.ok(response);f.calls.push({method:settings.method||'GET',path:new URL(url).pathname,status:response.status});if(f.transportAfter){const changed=await f.transportAfter(new URL(url).pathname,response,settings);if(changed!==undefined)response=changed;}return response;};
 f.bound=async(user='intern-a',key=keyPair())=>{if(f.actors.has(user))return f.actors.get(user);const token=f.bootstrap(user),c=succeeds(await f.call('/api/auth/devices/enrollment-challenges',{token,method:'POST',body:{publicKey:key.encoded,displayName:'Old synthetic '+user,platform:'win32',currentPassword:PASSWORD}})).data.challenge,r=succeeds(await f.call('/api/auth/devices/enroll',{token,method:'POST',body:{challengeId:c.challengeId,signature:sign(null,oldBytes(c),key.privateKey).toString('base64url')}}));const actor={user,key,session:r.data};f.actors.set(user,actor);return actor;};
 f.signedRequest=(route,{actor,method='GET',body,rawBody,serialized,nonce=randomBytes(32).toString('base64url')}={})=>{const bytes=Buffer.from(serialized??(rawBody===undefined?(body===undefined?'':JSON.stringify(body)):rawBody)),s=actor.session,u=new URL(ORIGIN+route),fields={serverId:s.lease.serverId,userId:actor.user,sessionBinding:digest(s.token),deviceId:s.device.id,bindingRevision:s.device.revision,leaseId:s.lease.id,method,pathAndQuery:u.pathname+u.search,bodySha256:digest(bytes),nonce};return f.request(route,{token:s.token,method,...(body!==undefined?{body}:{}),...(rawBody!==undefined?{rawBody}:{}),headers:{'X-Shenyi-Device-Lease':s.lease.token,'X-Shenyi-Device-Nonce':nonce,'X-Shenyi-Device-Body-SHA256':fields.bodySha256,'X-Shenyi-Device-Signature':sign(null,requestBytes(fields),actor.key.privateKey).toString('base64url')}});};
 f.protected=(route,options)=>f.send(f.signedRequest(route,options));
 f.candidate=async(user='intern-a',key=keyPair())=>{const old=await f.bound(user);return {user,key,token:f.bootstrap(user),old};};
 f.challenge=async(kind,candidate,{requestId=candidate.request?.id,revision=candidate.request?.revision,token=candidate.token,key=candidate.key}={})=>{const r=await f.call('/api/auth/device-replacements/'+kind+'-challenges',{token,method:'POST',body:kind==='request'?{publicKey:key.encoded,displayName:'New synthetic computer',platform:'darwin',currentPassword:PASSWORD}:{requestId,revision,publicKey:key.encoded}});succeeds(r,[201]);return {fields:r.data.challenge,kind,candidate,token,key};};
 f.complete=(challenge,{token=challenge.token,key=challenge.key,fields=challenge.fields,route=challenge.kind,domain='SHENYI-DEVICE-REPLACEMENT'}={})=>f.call('/api/auth/device-replacements/'+route,{token,method:'POST',body:{challengeId:challenge.fields.challengeId,signature:sign(null,payload(domain,fields,XF),key.privateKey).toString('base64url')}});
 f.create=async(candidate)=>{candidate??=await f.candidate();const c=await f.challenge('request',candidate),r=succeeds(await f.complete(c),[201]);candidate.request=r.data.request;return candidate;};
 f.review=async(candidate,{actor,decision='approve',revision=candidate.request.revision}={})=>{actor??=await f.bound(candidate.user==='tech-a'?'owner':'tech-a');return f.protected('/api/account/device-replacement-reviews/'+candidate.request.id+'/review',{actor,method:'POST',body:{revision,decision,currentPassword:PASSWORD}});};
 f.approve=async(candidate,options)=>{candidate??=await f.create();const r=succeeds(await f.review(candidate,options));candidate.request=r.data.request;return candidate;};
 f.activate=async(candidate,options)=>{const c=await f.challenge('activate',candidate,options),r=await f.complete(c,options);return {challenge:c,response:r};};
 f.rows=table=>{const stmt=db.prepare('SELECT * FROM '+table);stmt.setReadBigInts(true);return stmt.all().map(row=>JSON.stringify(Object.keys(row).sort().map(k=>[k,row[k] instanceof Uint8Array?['blob',Buffer.from(row[k]).toString('base64')]:typeof row[k]==='bigint'?['int',String(row[k])]:row[k]]))).sort();};
 f.auditData=()=>Object.fromEntries(preserveTables.map(table=>[table,f.rows(table)]));
 f.transactionData=()=>Object.fromEntries(db.prepare("SELECT name FROM sqlite_schema WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT IN ('team_auth_limits','team_device_request_replays') ORDER BY name").all().map(({name})=>[name,f.rows(name)]));
 return f;
}
function assertDto(value){assert.deepEqual(Object.keys(value).sort(),['id','teamId','teamName','displayName','targetKind','status','revision','createdAt','expiresAt','oldDevice','newDevice'].sort());assert.deepEqual(Object.keys(value.oldDevice).sort(),['id','displayName','platform','keyFingerprint','status','revision'].sort());assert.deepEqual(Object.keys(value.newDevice).sort(),['displayName','platform','keyFingerprint'].sort());for(const term of ['token','publicKey','password_hash','approval_stamp','target_stamp','session_binding','phone','private-provider'])assert.ok(!JSON.stringify(value).includes(term));}
const taskPath='/api/teams/team-a/collection/tasks';

test('approval retains the old business session; explicit new-key activation alone replaces it and preserves all audit data',async t=>{const f=await fixture(t),candidate=await f.create(),old=candidate.old;const original=Buffer.from('Synthetic replacement original\0\r\n原件');const upload=succeeds(await f.protected(taskPath+'/task-a/submissions',{actor:old,method:'POST',body:{filename:'synthetic.bin',contentBase64:original.toString('base64'),revision:0}}));const before=f.auditData();await f.approve(candidate);assertDto(candidate.request);assert.equal(candidate.request.status,'approved');assert.equal((await f.protected(taskPath,{actor:old})).status,200);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_bindings WHERE user_id='intern-a'").get().n,1);const result=succeeds((await f.activate(candidate)).response);assert.equal(result.data.device.keyFingerprint,candidate.key.fingerprint);assert.equal(result.data.device.platform,'darwin');assert.equal(result.data.lease.expiresAt,result.data.expiresAt);assert.equal(result.data.expiresAt-f.now,900000);assert.deepEqual(f.auditData(),before);rejected(await f.protected(taskPath,{actor:old}),[401]);const replacement={user:candidate.user,key:candidate.key,session:result.data};assert.equal((await f.protected(taskPath,{actor:replacement})).status,200);const bytes=await f.protected(taskPath+'/task-a/attachments/'+upload.data.submission.attachmentId,{actor:replacement});assert.deepEqual(bytes.bytes,original);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_bindings WHERE user_id='intern-a' AND status='active'").get().n,1);assert.equal(f.db.prepare("SELECT status FROM team_device_replacement_requests WHERE request_id=?").get(candidate.request.id).status,'claimed');});

test('old challenge cannot move to a new bootstrap, while an explicit fresh same-key activation challenge permits approved resume',async t=>{const f=await fixture(t),r=await f.approve(),oldChallenge=await f.challenge('activate',r),stamp=f.db.prepare('SELECT target_stamp,approval_stamp FROM team_device_replacement_requests WHERE request_id=?').get(r.request.id),fresh=f.bootstrap(r.user);rejected(await f.complete(oldChallenge,{token:fresh}),[403,404]);const status=succeeds(await f.call('/api/auth/device-replacements',{token:fresh}));assert.equal(status.data.request.id,r.request.id);assert.equal(status.data.request.status,'approved');const freshChallenge=await f.challenge('activate',r,{token:fresh});assert.notEqual(freshChallenge.fields.sessionBinding,oldChallenge.fields.sessionBinding);assert.equal(freshChallenge.fields.sessionBinding,digest(fresh));succeeds(await f.complete(freshChallenge));assert.deepEqual(f.db.prepare('SELECT target_stamp,approval_stamp FROM team_device_replacement_requests WHERE request_id=?').get(r.request.id),stamp);});

for(const field of XF)test(`replacement signature cannot transfer altered ${field}`,async t=>{const f=await fixture(t),r=await f.candidate(),c=await f.challenge('request',r),fields={...c.fields};const substitutions={purpose:'activate',serverId:randomUUID(),userId:'assistant-b',sessionBinding:'0'.repeat(64),keyFingerprint:'0'.repeat(64),identityEpoch:fields.identityEpoch+1,oldDeviceId:randomUUID(),oldBindingRevision:fields.oldBindingRevision+1,oldBindingStatus:'revoked',requestId:randomUUID(),requestRevision:1,challengeId:randomUUID(),nonce:randomBytes(32).toString('base64url'),issuedAt:fields.issuedAt+1,expiresAt:fields.expiresAt+1};fields[field]=substitutions[field];rejected(await f.complete(c,{fields}),[403]);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM team_device_replacement_requests').get().n,0);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_bindings WHERE user_id='intern-a'").get().n,1);});

test('existing device domain, wrong private key and wrong route cannot create a replacement request',async t=>{const f=await fixture(t),r=await f.candidate(),c=await f.challenge('request',r);rejected(await f.complete(c,{domain:'SHENYI-DEVICE-PROOF'}),[403]);rejected(await f.complete(c,{key:keyPair()}),[403]);rejected(await f.complete(c,{route:'activate'}),[403,404]);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM team_device_replacement_requests').get().n,0);});

test('cross-account and cross-session completion are opaque and never consume the real challenge',async t=>{const f=await fixture(t),r=await f.candidate(),c=await f.challenge('request',r);for(const token of [f.bootstrap('assistant-b'),f.bootstrap('intern-a')])rejected(await f.complete(c,{token}),[403,404]);assert.equal(f.db.prepare('SELECT consumed_at FROM team_device_replacement_challenges WHERE challenge_id=?').get(c.fields.challengeId).consumed_at,null);succeeds(await f.complete(c),[201]);});

test('five invalid signatures retire a replacement challenge without touching the old binding or session',async t=>{const f=await fixture(t),r=await f.candidate(),c=await f.challenge('request',r),wrong=keyPair();for(let i=0;i<5;i++)rejected(await f.complete(c,{key:wrong}),[403]);rejected(await f.complete(c),[409]);const row=f.db.prepare('SELECT attempts,revoked_at FROM team_device_replacement_challenges WHERE challenge_id=?').get(c.fields.challengeId);assert.equal(row.attempts,5);assert.ok(row.revoked_at!==null);assert.equal((await f.protected(taskPath,{actor:r.old})).status,200);});

test('concurrent valid request completions produce one open request and one request event',async t=>{const f=await fixture(t),r=await f.candidate(),a=await f.challenge('request',r),b=await f.challenge('request',r),results=await Promise.all([f.complete(a),f.complete(b)]);assert.equal(results.filter(x=>x.status===201).length,1);rejected(results.find(x=>x.status!==201),[409]);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_replacement_requests WHERE status IN ('pending','approved')").get().n,1);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_replacement_events WHERE action='request'").get().n,1);});

test('concurrent approvals and activations are one-shot while the old binding is retained until activation',async t=>{const f=await fixture(t),r=await f.create(),actor=await f.bound('tech-a'),reviews=await Promise.all([f.review(r,{actor}),f.review(r,{actor})]);assert.equal(reviews.filter(x=>x.status===200).length,1);rejected(reviews.find(x=>x.status!==200),[409]);r.request=reviews.find(x=>x.status===200).data.request;assert.equal((await f.protected(taskPath,{actor:r.old})).status,200);const a=await f.challenge('activate',r),b=await f.challenge('activate',r),results=await Promise.all([f.complete(a),f.complete(b)]);assert.equal(results.filter(x=>[200,201].includes(x.status)).length,1);rejected(results.find(x=>![200,201].includes(x.status)),[401,409]);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_replacement_events WHERE action='claim'").get().n,1);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_bindings WHERE user_id='intern-a'").get().n,2);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_leases WHERE user_id='intern-a' AND revoked_at IS NULL").get().n,1);});

for(const reviewer of ['manager-a','partner-a','tech-b','provision-owner','recovery-owner','access-owner'])test(`${reviewer} has no inherited employee replacement approval`,async t=>{const f=await fixture(t),r=await f.create(),actor=await f.bound(reviewer);rejected(await f.review(r,{actor}),[404]);const list=await f.protected('/api/account/device-replacement-reviews',{actor});if(list.status===200)assert.ok(!list.data.requests.some(x=>x.id===r.request.id));else rejected(list,[404]);assert.equal(f.db.prepare('SELECT status FROM team_device_replacement_requests WHERE request_id=?').get(r.request.id).status,'pending');});

test('administrator replacement requires the independent device owner, never self or unrelated owner grants',async t=>{const f=await fixture(t),r=await f.create(await f.candidate('tech-a'));for(const user of ['tech-a','tech-b','provision-owner','recovery-owner','access-owner'])rejected(await f.review(r,{actor:await f.bound(user)}),[404]);await f.approve(r,{actor:await f.bound('owner')});assert.equal(r.request.targetKind,'administrator');assert.equal((await f.protected('/api/account/device-replacement-reviews/access',{actor:await f.bound('owner')})).data.canReview,true);succeeds((await f.activate(r)).response);});

test('a mistakenly granted device owner ACL cannot turn an intern into an administrator reviewer',async t=>{const f=await fixture(t),r=await f.create(await f.candidate('tech-a')),junior=await f.bound('intern-a');f.db.prepare("INSERT INTO team_device_replacement_reviewers VALUES ('intern-a','device.replace','active',1)").run();rejected(await f.review(r,{actor:junior}),[403,404,409]);assert.equal(f.db.prepare('SELECT status FROM team_device_replacement_requests WHERE request_id=?').get(r.request.id).status,'pending');});

for(const table of ['team_platform_reviewers','team_recovery_reviewers','team_access_reviewers','team_device_replacement_reviewers'])test(`any historic ${table} record protects a target from ordinary replacement`,async t=>{const f=await fixture(t),candidate=await f.candidate(),permission={team_platform_reviewers:'team.provision',team_recovery_reviewers:'account.recover',team_access_reviewers:'member.disable',team_device_replacement_reviewers:'device.replace'}[table];f.db.prepare(`INSERT INTO ${table} VALUES ('intern-a',?,'revoked',1)`).run(permission);const status=succeeds(await f.call('/api/auth/device-replacements',{token:candidate.token}));assert.equal(status.data.canRequest,false);rejected(await f.call('/api/auth/device-replacements/request-challenges',{token:candidate.token,method:'POST',body:{publicKey:candidate.key.encoded,displayName:'Synthetic',platform:'win32',currentPassword:PASSWORD}}),[404]);});

for(const mutation of ['multi-team','operator-history','inactive-membership','disabled-team','disabled-user'])test(`target ${mutation} cannot start a replacement`,async t=>{const f=await fixture(t),r=await f.candidate();if(mutation==='multi-team')f.db.prepare("INSERT INTO team_memberships VALUES ('team-b','intern-a','intern','disabled')").run();if(mutation==='operator-history')f.db.prepare("INSERT INTO team_operators VALUES ('team-a','intern-a','administrator','revoked')").run();if(mutation==='inactive-membership')f.db.prepare("UPDATE team_memberships SET status='disabled' WHERE user_id='intern-a'").run();if(mutation==='disabled-team')f.db.prepare("UPDATE teams SET status='disabled' WHERE team_id='team-a'").run();if(mutation==='disabled-user')f.db.prepare("UPDATE team_users SET status='disabled' WHERE user_id='intern-a'").run();rejected(await f.call('/api/auth/device-replacements/request-challenges',{token:r.token,method:'POST',body:{publicKey:r.key.encoded,displayName:'Synthetic',platform:'win32',currentPassword:PASSWORD}}),[401,404]);assert.equal(f.db.prepare('SELECT COUNT(*) n FROM team_device_replacement_requests').get().n,0);});

test('active same-key is not replacement, while revoked same-key history can be explicitly reviewed and recovered',async t=>{const f=await fixture(t),old=await f.bound(),token=f.bootstrap('intern-a');rejected(await f.call('/api/auth/device-replacements/request-challenges',{token,method:'POST',body:{publicKey:old.key.encoded,displayName:'Same key',platform:'win32',currentPassword:PASSWORD}}),[409]);const c=succeeds(await f.call('/api/auth/devices/revocation-challenges',{token,method:'POST',body:{publicKey:old.key.encoded,revision:1,currentPassword:PASSWORD}})).data.challenge;succeeds(await f.call('/api/auth/devices/revoke',{token,method:'POST',body:{challengeId:c.challengeId,signature:sign(null,oldBytes(c),old.key.privateKey).toString('base64url')}}));const revokedBefore=f.rows('team_device_bindings'),r=await f.approve(await f.create({user:'intern-a',key:old.key,token:f.bootstrap('intern-a'),old}));
 assert.equal(r.request.oldDevice.status,'revoked');succeeds((await f.activate(r)).response);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM team_device_bindings WHERE user_id='intern-a' AND status='active'").get().n,1);for(const row of revokedBefore)assert.ok(f.rows('team_device_bindings').includes(row),'Revoked history is retained unchanged');});

