test('review list scopes before bounded projection even when newer foreign records dominate the global table',async t=>{const f=await fixture(t),own=await f.create(),foreign=await f.create(await f.candidate('assistant-b')),actor=await f.bound('tech-a'),copies=(candidate,count,base)=>{const row=f.db.prepare('SELECT * FROM team_device_replacement_requests WHERE request_id=?').get(candidate.request.id),names=Object.keys(row),insert=f.db.prepare(`INSERT INTO team_device_replacement_requests(${names.join(',')}) VALUES (${names.map(()=>'?').join(',')})`);for(let i=0;i<count;i++){const copy={...row,request_id:randomUUID(),status:'rejected',created_at:base+i};insert.run(...names.map(name=>copy[name]));}};copies(own,51,NOW+100);copies(foreign,800,NOW+10000);const original=f.db.prepare;let scanned=0;f.db.prepare=function(sql){const statement=original.call(this,sql);if(/FROM\s+team_device_replacement_requests\b/i.test(sql)&&!/WHERE\s+request_id\s*=/i.test(sql)){const all=statement.all;statement.all=function(...args){assert.match(sql,/team_id/,'Candidate list must carry tenant scope in SQL');assert.match(sql,/LIMIT/i,'Materialized candidate list must be bounded');const rows=all.apply(this,args);scanned+=rows.length;assert.ok(rows.length<=51);return rows;};}return statement;};t.after(()=>{f.db.prepare=original;});const result=succeeds(await f.protected('/api/account/device-replacement-reviews',{actor}));assert.equal(result.data.requests.length,50);assert.equal(result.data.hasMore,true);assert.ok(result.data.requests.every(row=>row.teamId==='team-a'));for(const row of result.data.requests)assertDto(row);assert.ok(scanned<=51);});

function duringQuota(t,f,prefix,mutate){const original=f.db.prepare;let hit=false;f.db.prepare=function(sql){const statement=original.call(this,sql);if(sql==='SELECT window_start,attempts FROM team_auth_limits WHERE bucket=?'){const get=statement.get;statement.get=function(bucket){const value=get.call(this,bucket);if(!hit&&bucket.startsWith(prefix)){hit=true;queueMicrotask(mutate);}return value;};}return statement;};t.after(()=>{f.db.prepare=original;});return ()=>hit;}
