function memoryVault(key){return {async getPublicIdentity(){return {publicKey:key.encoded,fingerprint:key.fingerprint};},async signChallenge(fields,context){for(const name of ['purpose','serverId','userId','bindingRevision'])assert.equal(fields[name],context[name]);assert.equal(fields.sessionBinding,digest(context.sessionToken));assert.equal(fields.keyFingerprint,key.fingerprint);return sign(null,oldBytes(fields),key.privateKey).toString('base64url');},async signRequest(fields,context){for(const name of ['serverId','userId','deviceId','bindingRevision','leaseId'])assert.equal(fields[name],context[name]);assert.equal(fields.sessionBinding,digest(context.sessionToken));assert.equal(context.keyFingerprint,key.fingerprint);return sign(null,requestBytes(fields),key.privateKey).toString('base64url');},async signReplacementChallenge(fields,context){assert.deepEqual(Object.keys(context).sort(),['purpose','serverId','userId','sessionToken','oldDeviceId','oldBindingRevision','oldBindingStatus','requestId','requestRevision'].sort());for(const name of ['purpose','serverId','userId','oldDeviceId','oldBindingRevision','oldBindingStatus','requestId','requestRevision'])assert.equal(fields[name],context[name]);assert.equal(fields.sessionBinding,digest(context.sessionToken));assert.equal(fields.keyFingerprint,key.fingerprint);return sign(null,replacementBytes(fields),key.privateKey).toString('base64url');},dispose(){}};}
function normalClient(t,f,key){const client=createTeamClient({fetchImpl:f.transport,now:()=>f.now,deviceIdentity:{vault:memoryVault(key),platform:'win32',displayName:'Synthetic main computer'}});t.after(()=>client.clearSession());return client;}
async function approvedClient(t,f){const old=await f.bound(),key=keyPair(),client=normalClient(t,f,key);assert.equal((await client.login({username:'intern-a',password:PASSWORD})).device.state,'different_key');const result=await client.requestDeviceReplacement({displayName:'New synthetic main',currentPassword:PASSWORD,confirmed:true}),candidate={user:'intern-a',old,key,request:result.request};await f.approve(candidate);return {client,candidate};}
function desktopBridge(t,client,dialog={}){const handlers=new Map(),frame={url:APP_URL},window={webContents:{mainFrame:frame}},dispose=registerDesktopBridge({ipcMain:{handle:(name,action)=>handlers.set(name,action),removeHandler:name=>handlers.delete(name)},window,client,dialog:{showOpenDialog:async()=>({canceled:true,filePaths:[]}),showSaveDialog:async()=>({canceled:true}),...dialog}});t.after(dispose);const event={sender:window.webContents,senderFrame:frame};return {handlers,call:(name,input)=>handlers.get('shenyi:'+name)(event,input)};}

